use aap::caps::http_client;

struct Node;

/// The exact hosts this node's `with HTTPClient<[...]>` clause names.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the lowercase host of an http(s) URL, or `None` if the URL is
/// malformed or uses constructs (userinfo, IPv6 literals) this node refuses
/// to reason about. Anything `None` is treated as outside the allowlist.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#', '\\']).next()?;
    if authority.is_empty() || authority.contains('@') || authority.starts_with('[') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

fn in_allowlist(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.contains(&host.as_str()),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            // Fail closed on our side too: an out-of-scope URL is recorded as a
            // failure rather than reaching the host, where it would trap the run.
            if !in_allowlist(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in node's allowlist".to_string(),
                });
                continue;
            }

            // `fetch` returns transport failures (timeout, status, size cap) as
            // values, so one dead feed does not fail the whole batch.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch { documents, failures }
    }
}

export!(Node);
```

I did not import `aap:caps/state-rw` or write `last-input`. The node's `with` clause grants only `aap:caps/http-client@0.1.0`, and the graph definition is the authority for what a node may touch. A platform approval mentioned in a request doesn't change that. Once the graph is updated to grant `state-rw`, the world and body can be extended to match. The output above is unaffected by that omission.

